attempts.sql:
SELECT c.name, c.artist, c.isPromo
FROM cards c
JOIN rulings r ON r.uuid = c.uuid
GROUP BY c.uuid, c.name, c.artist, c.isPromo
HAVING COUNT(r.uuid) = (
  SELECT MAX(cnt) FROM (
    SELECT COUNT(*) AS cnt FROM rulings GROUP BY uuid
  )
);

SELECT CAST(SUM(CASE WHEN Admission = '-' THEN 1 ELSE 0 END) AS REAL) / NULLIF(SUM(CASE WHEN Admission = '+' THEN 1 ELSE 0 END), 0) AS outpatient_to_inpatient_ratio
FROM Patient
WHERE Diagnosis = 'SLE';

